                ds.totalTaxImpact += totalRoundCost;
                ds.etrHistory.push(ds.effectiveTaxRate);
                ds.reputationHistory.push(ds.reputationScore);
                ds.auditRiskHistory.push(Math.round(ds.auditRiskScore));
                ds.taxImpactHistory.push(Math.round(totalRoundCost / 1000000));

            } else if (period === 3) {
                var exitTax = 0;
                var annualCostNew = 0;
                var newETR = ds.effectiveTaxRate;
                var researcherCost = d.researchersToHire * 80000;
                var substanceScore = Math.min(100, d.researchersToHire * 7);

                if (d.ipDestination === 1) {
                    exitTax = 5950000;
                    var patentBoxRate = 10;
                    if (d.researchersToHire >= 8) {
                        newETR = 19.5;
                        annualCostNew = researcherCost;
                        ds.reputationScore += 10;
                        ds.auditRiskScore = Math.max(10, ds.auditRiskScore - 15);
                    } else {
                        newETR = 22;
                        annualCostNew = researcherCost;
                        ds.reputationScore += 5;
                    }
                    ds.ipLocation = 'spain_patent_box';
                } else if (d.ipDestination === 2) {
                    exitTax = 5950000;
                    newETR = 17.5;
                    annualCostNew = researcherCost + 200000;
                    ds.reputationScore -= 3;
                    ds.auditRiskScore = Math.min(100, ds.auditRiskScore + 5);
                    ds.ipLocation = 'ireland_kdb';
                } else if (d.ipDestination === 3) {
                    exitTax = 0;
                    if (d.researchersToHire >= 15) {
                        newETR = 18.8;
                        ds.auditRiskScore = Math.max(10, ds.auditRiskScore - 10);
                    } else {
                        newETR = 20;
                        ds.auditRiskScore = Math.min(100, ds.auditRiskScore + 15);
                    }
                    annualCostNew = researcherCost;
                    ds.ipLocation = 'netherlands_strengthened';
                } else {
                    exitTax = 5950000;
                    newETR = 22.5;
                    annualCostNew = 0;
                    ds.reputationScore += 15;
                    ds.auditRiskScore = Math.max(5, ds.auditRiskScore - 25);
                    ds.ipLocation = 'spain_direct';
                }

                var annualTaxSavings = ds.groupEBIT * ((ds.effectiveTaxRate - newETR) / 100);
                var paybackYears = exitTax > 0 ? (exitTax / Math.max(1, (annualTaxSavings - annualCostNew))) : 0;
                if (paybackYears < 0 || paybackYears > 99) paybackYears = 99;

                ds.cashReserves -= Math.round(exitTax / 5);
                ds.exitTaxCost = exitTax;
                ds.annualSavings = Math.round(annualTaxSavings);
                ds.effectiveTaxRate = Math.round(newETR * 10) / 10;

                results.ipDestination = d.ipDestination;
                results.researchersHired = d.researchersToHire;
                results.exitTax = exitTax;
                results.annualResearcherCost = annualCostNew;
                results.newETR = newETR;
                results.annualTaxSavings = Math.round(annualTaxSavings);
                results.paybackYears = Math.round(paybackYears * 10) / 10;
                results.substanceScore = substanceScore;
                results.taxImpact = Math.round(exitTax / 5);
                results.reputationChange = ds.reputationScore - ds.reputationHistory[ds.reputationHistory.length - 1];

                ds.totalTaxImpact += Math.round(exitTax / 5);
                ds.etrHistory.push(newETR);
                ds.reputationHistory.push(ds.reputationScore);
                ds.auditRiskHistory.push(Math.round(ds.auditRiskScore));
                ds.taxImpactHistory.push(Math.round(exitTax / 5000000));

            } else if (period === 4) {
                var repBonus = 0;
                var riskChange = 0;

                if (d.cbcrDecision === 1) {
                    repBonus += 12;
                    riskChange -= 15;
                } else if (d.cbcrDecision === 2) {
                    repBonus += 5;
                    riskChange -= 5;
                } else {
                    repBonus -= 3;
                    riskChange += 5;
                }

                if (d.taxPolicyDecision === 1) {
                    repBonus += 15;
                    riskChange -= 10;
                } else if (d.taxPolicyDecision === 2) {
                    repBonus += 5;
                    riskChange -= 3;
                } else {
                    repBonus -= 5;
                    riskChange += 5;
                }

                if (d.optimizationStance === 1) {
                    repBonus += 10;
                    riskChange -= 10;
                    ds.effectiveTaxRate = Math.min(25, ds.effectiveTaxRate + 1.5);
                } else if (d.optimizationStance === 2) {
                    repBonus += 3;
                    riskChange -= 3;
                } else {
                    repBonus -= 10;
                    riskChange += 20;
                    ds.effectiveTaxRate = Math.max(15, ds.effectiveTaxRate - 2);
                }

                ds.reputationScore = Math.min(100, Math.max(0, ds.reputationScore + repBonus));
                ds.auditRiskScore = Math.min(100, Math.max(0, ds.auditRiskScore + riskChange));

                var finalTaxBill = Math.round(ds.groupEBIT * (ds.effectiveTaxRate / 100));

                results.cbcrDecision = d.cbcrDecision;
                results.taxPolicyDecision = d.taxPolicyDecision;
                results.optimizationStance = d.optimizationStance;
                results.reputationBonus = repBonus;
                results.riskChange = riskChange;
                results.finalETR = ds.effectiveTaxRate;
                results.finalReputationScore = ds.reputationScore;
                results.finalAuditRisk = Math.round(ds.auditRiskScore);
                results.annualTaxBill = finalTaxBill;
                results.taxImpact = finalTaxBill;
                results.reputationChange = repBonus;

                ds.etrHistory.push(ds.effectiveTaxRate);
                ds.reputationHistory.push(ds.reputationScore);
                ds.auditRiskHistory.push(Math.round(ds.auditRiskScore));
                ds.taxImpactHistory.push(Math.round(finalTaxBill / 1000000));
            }

            // platform score: the getPerformanceSummary bands (ETR, reputation, audit risk, total cost, already on a 0-100 scale) applied to the state so far
            state.domainState.performance = Object.assign({}, state.domainState.performance || {}, {
                overallScore: this._runningScore(ds)
            });

            var self = this;
            /* v1.1.0: the framework increments currentPeriod synchronously before this 500ms callback fires, so the originals read the WRONG period: _updateBriefing({currentPeriod: state.currentPeriod + 1}) rendered period N+2 (a round became unreachable) and _showResults(state.currentPeriod, ...) labelled round N's results as round N+1. Now: _updateBriefing reads the live post-increment period (N+1), and _showResults uses results.period (the round just computed, N -- correct on the final round too, where the framework does not increment). The 500ms results-panel dwell is preserved. */
            setTimeout(function() {
                self._updateBriefing(window.mySimulation.state);
                self._showResults(results.period, results, ds);
            }, 500);

            return results;
        }

        _showResults(period, results, ds) {
