                html += t('res2_legal') + ': ' + (results.legalCost / 1000).toFixed(0) + 'K<br>';
                html += t('res2_penalty') + ': ' + (results.penaltyAmount / 1000000).toFixed(2) + 'M<br>';
                html += t('res2_total') + ': <b>' + (results.totalRoundCost / 1000000).toFixed(2) + 'M</b><br>';
                html += t('res2_certainty') + ': ' + results.certaintyScore + '%<br>';
                html += t('res2_map') + ': ' + (results.mapOpened ? t('res_yes') : t('res_no'));
            } else if (period === 3) {
                html = '<b>' + t('res3_heading') + '</b><br>';
                html += t('res3_ip') + ': ' + t('res3_ip_' + results.ipDestination) + '<br>';
                html += t('res3_researchers') + ': ' + results.researchersHired + '<br>';
                html += t('res3_exit_tax') + ': ' + (results.exitTax / 1000000).toFixed(2) + 'M<br>';
                html += t('res3_new_etr') + ': <b>' + results.newETR + '%</b><br>';
                html += t('res3_savings') + ': ' + (results.annualTaxSavings / 1000000).toFixed(2) + 'M<br>';
                html += t('res3_payback') + ': ' + results.paybackYears + ' ' + t('res3_years') + '<br>';
                html += t('res3_substance') + ': ' + results.substanceScore + '/100';
            } else if (period === 4) {
                html = '<b>' + t('res4_heading') + '</b><br>';
                html += t('res4_etr') + ': <b>' + results.finalETR + '%</b><br>';
                html += t('res4_reputation') + ': <b>' + results.finalReputationScore + '/100</b><br>';
                html += t('res4_risk') + ': ' + results.finalAuditRisk + '%<br>';
                html += t('res4_bill') + ': ' + (results.annualTaxBill / 1000000).toFixed(2) + 'M';
            }
            textEl.innerHTML = html;
        }

