        _runningScore(ds) {
            var finalETR = ds.effectiveTaxRate || 20;
            var finalRep = typeof ds.reputationScore === 'number' ? ds.reputationScore : 50;
            var finalRisk = (typeof ds.auditRiskScore === 'number') ? ds.auditRiskScore : 50;
            var totalCost = ds.totalTaxImpact || 0;
            var score = 0;
            if (finalETR <= 20) score += 25;
            else if (finalETR <= 22) score += 15;
            if (finalRep >= 75) score += 30;
            else if (finalRep >= 55) score += 15;
            if (finalRisk <= 25) score += 25;
            else if (finalRisk <= 45) score += 15;
            if (totalCost < 8000000) score += 20;
            else if (totalCost < 12000000) score += 10;
            return Math.max(0, Math.min(100, Math.round(score)));
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var lastRecord = history[history.length - 1];
            var ds = window.mySimulation.state.domainState;

            var finalETR = ds.effectiveTaxRate || 20;
            var finalRep = typeof ds.reputationScore === 'number' ? ds.reputationScore : 50;
            var finalRisk = (typeof ds.auditRiskScore === 'number') ? ds.auditRiskScore : 50;
            var totalCost = ds.totalTaxImpact || 0;

            var score = 0;
            if (finalETR <= 20) score += 25;
            else if (finalETR <= 22) score += 15;
            if (finalRep >= 75) score += 30;
            else if (finalRep >= 55) score += 15;
            if (finalRisk <= 25) score += 25;
            else if (finalRisk <= 45) score += 15;
            if (totalCost < 8000000) score += 20;
            else if (totalCost < 12000000) score += 10;

            var performance = this._t('perf_needs_improvement');
            if (score >= 80) performance = this._t('perf_excellent');
            else if (score >= 60) performance = this._t('perf_competent');
            else if (score >= 40) performance = this._t('perf_developing');

            var insights = [];
            if (finalETR > 22) insights.push(this._t('ins_etr_high'));
            if (finalRep < 50) insights.push(this._t('ins_rep_low'));
            if (finalRisk > 50) insights.push(this._t('ins_risk_high'));
            if (finalRep >= 75 && finalRisk <= 25) insights.push(this._t('ins_balance'));

            return {
                finalETR: finalETR,
                finalReputation: finalRep,
                finalAuditRisk: finalRisk,
                totalCost: totalCost,
                score: score,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            var period = state.currentPeriod;
            if (period === 1 && results.analysisScore < 50) {
                return window.mySimulation.t('hint_r1_low');
