            if (period === 2 && results.certaintyScore < 50) {
                return window.mySimulation.t('hint_r2_certainty');
            }
            if (period === 3 && results.substanceScore < 50) {
                return window.mySimulation.t('hint_r3_substance');
            }
            if (period === 4 && state.domainState.auditRiskScore > 50) {
                return window.mySimulation.t('hint_r4_risk');
            }
            return null;
        }

