        _t(key) {
            if (window.mySimulation && typeof window.mySimulation.t === 'function') return window.mySimulation.t(key);
            return key;
        }

        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            var briefTitle = document.getElementById('briefingTitle');
            if (briefTitle) briefTitle.innerHTML = this._t(round.titleKey);

            var briefText = document.getElementById('briefingText');
            if (briefText) briefText.innerHTML = this._t(round.descKey);

            var roundInputIds = ['round1Inputs', 'round2Inputs', 'round3Inputs', 'round4Inputs'];
            for (var i = 0; i < roundInputIds.length; i++) {
                var el = document.getElementById(roundInputIds[i]);
                if (el) el.style.display = (i === idx) ? 'block' : 'none';
            }

            var resultsPanel = document.getElementById('roundResultsPanel');
            if (resultsPanel) resultsPanel.style.display = 'none';

            this._updateOptionTexts();
        }

        _updateOptionTexts() {
            // option texts set by option value, not by position, so a placeholder or reorder can never mislabel them
            var self = this;
            var texts = {
                royaltyStrategySelect: { '1': 'opt_royalty_1', '2': 'opt_royalty_2', '3': 'opt_royalty_3' },
                disputeStrategySelect: { '1': 'opt_dispute_1', '2': 'opt_dispute_2', '3': 'opt_dispute_3' },
                mapProcedureSelect: { '1': 'opt_map_1', '0': 'opt_map_0' },
                ipDestinationSelect: { '1': 'opt_ip_1', '2': 'opt_ip_2', '3': 'opt_ip_3', '4': 'opt_ip_4' },
                cbcrSelect: { '1': 'opt_cbcr_1', '2': 'opt_cbcr_2', '3': 'opt_cbcr_3' },
                taxPolicySelect: { '1': 'opt_policy_1', '2': 'opt_policy_2', '3': 'opt_policy_3' },
                optimizationSelect: { '1': 'opt_stance_1', '2': 'opt_stance_2', '3': 'opt_stance_3' }
            };
            Object.keys(texts).forEach(function(id) {
                var sel = document.getElementById(id);
                if (!sel) return;
                for (var i = 0; i < sel.options.length; i++) {
                    var key = texts[id][sel.options[i].value];
                    if (key) sel.options[i].text = self._t(key);
                }
            });
        }
    }

    document.addEventListener('DOMContentLoaded', function() {
        window.mySimulation = new USF.SimulationFramework();
        window.mySimulation.initialize(new ImpuestoAdapter(), {
            simulationType: 'impuesto_tax_planning',
            maxPeriods: 4,
            autoSaveInterval: 30000
        });
    });

